import{_ as o,o as t,c as a,l as s,t as r,N as i}from"./chunks/framework.CMqbtke2.js";const k=JSON.parse('{"title":"git-web--browse | x-cmd man (git man1) | Git helper script to launch a web browser","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-web--browse - Git helper script to launch a web browser","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-web--browse | x-cmd man (git man1) | Git helper script to launch a web browser"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-web--browse - Git helper script to launch a web browser"}]]},"headers":[],"params":{"isMan":true,"man":"git-web--browse","category":"git man1","desc":"Git helper script to launch a web browser"},"relativePath":"git/man1/git-web--browse.md","filePath":"git/man1/git-web--browse.md"}'),n={name:"git/man1/git-web--browse.md"},l={class:"visually-hidden"},p=i(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-web--browse - Git helper script to launch a web browser</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web--browse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;|&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)...</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This script tries, as much as possible, to display the URLs and FILEs that are passed as arguments, as HTML pages in new tabs on an already opened web browser.</p><p>The following browsers (or commands) are currently supported:</p><blockquote><p>·</p><p>firefox (this is the default under X Window when not using KDE)</p></blockquote><blockquote><p>·</p><p>iceweasel</p></blockquote><blockquote><p>·</p><p>seamonkey</p></blockquote><blockquote><p>·</p><p>iceape</p></blockquote><blockquote><p>·</p><p>chromium (also supported as chromium-browser)</p></blockquote><blockquote><p>·</p><p>google-chrome (also supported as chrome)</p></blockquote><blockquote><p>·</p><p>konqueror (this is the default under KDE, see <em>Note about konqueror</em> below)</p></blockquote><blockquote><p>·</p><p>opera</p></blockquote><blockquote><p>·</p><p>w3m (this is the default outside graphical environments)</p></blockquote><blockquote><p>·</p><p>elinks</p></blockquote><blockquote><p>·</p><p>links</p></blockquote><blockquote><p>·</p><p>lynx</p></blockquote><blockquote><p>·</p><p>dillo</p></blockquote><blockquote><p>·</p><p>open (this is the default under Mac OS X GUI)</p></blockquote><blockquote><p>·</p><p>start (this is the default under MinGW)</p></blockquote><blockquote><p>·</p><p>cygstart (this is the default under Cygwin)</p></blockquote><blockquote><p>·</p><p>xdg-open</p></blockquote><p>Custom commands may also be specified.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-b &lt;browser&gt;, --browser=&lt;browser&gt;</p><blockquote><p>Use the specified browser. It must be in the list of supported browsers.</p></blockquote><p>-t &lt;browser&gt;, --tool=&lt;browser&gt;</p><blockquote><p>Same as above.</p></blockquote><p>-c &lt;conf.var&gt;, --config=&lt;conf.var&gt;</p><blockquote><p>CONF.VAR is looked up in the Git config files. If it&#39;s set, then its value specifies the browser that should be used.</p></blockquote><h2 id="configuration-variables" tabindex="-1">CONFIGURATION VARIABLES <a class="header-anchor" href="#configuration-variables" aria-label="Permalink to &quot;CONFIGURATION VARIABLES&quot;">​</a></h2><h3 id="conf-var-from-c-option-and-web-browser" tabindex="-1">CONF.VAR (from -c option) and web.browser <a class="header-anchor" href="#conf-var-from-c-option-and-web-browser" aria-label="Permalink to &quot;CONF.VAR (from -c option) and web.browser&quot;">​</a></h3><p>The web browser can be specified using a configuration variable passed with the -c (or --config) command-line option, or the <strong>web.browser</strong> configuration variable if the former is not used.</p><h3 id="browser-tool-path" tabindex="-1">browser.&lt;tool&gt;.path <a class="header-anchor" href="#browser-tool-path" aria-label="Permalink to &quot;browser.\\&lt;tool\\&gt;.path&quot;">​</a></h3><p>You can explicitly provide a full path to your preferred browser by setting the configuration variable <strong>browser.&lt;tool&gt;.path</strong>. For example, you can configure the absolute path to firefox by setting <em>browser.firefox.path</em>. Otherwise, <em>git web--browse</em> assumes the tool is available in PATH.</p><h3 id="browser-tool-cmd" tabindex="-1">browser.&lt;tool&gt;.cmd <a class="header-anchor" href="#browser-tool-cmd" aria-label="Permalink to &quot;browser.\\&lt;tool\\&gt;.cmd&quot;">​</a></h3><p>When the browser, specified by options or configuration variables, is not among the supported ones, then the corresponding <strong>browser.&lt;tool&gt;.cmd</strong> configuration variable will be looked up. If this variable exists then <em>git web--browse</em> will treat the specified tool as a custom command and will use a shell eval to run the command with the URLs passed as arguments.</p><h2 id="note-about-konqueror" tabindex="-1">NOTE ABOUT KONQUEROR <a class="header-anchor" href="#note-about-konqueror" aria-label="Permalink to &quot;NOTE ABOUT KONQUEROR&quot;">​</a></h2><p>When <em>konqueror</em> is specified by a command-line option or a configuration variable, we launch <em>kfmclient</em> to try to open the HTML man page on an already opened konqueror in a new tab if possible.</p><p>For consistency, we also try such a trick if <em>browser.konqueror.path</em> is set to something like <strong>A_PATH_TO/konqueror</strong>. That means we will try to launch <strong>A_PATH_TO/kfmclient</strong> instead.</p><p>If you really want to use <em>konqueror</em>, then you can use something like the following:</p><blockquote><pre><code>        [web]
                browser = konq

        [browser &quot;konq&quot;]
                cmd = A_PATH_TO/konqueror
</code></pre></blockquote><h3 id="note-about-git-config-global" tabindex="-1">Note about git-config --global <a class="header-anchor" href="#note-about-git-config-global" aria-label="Permalink to &quot;Note about git-config \\--global&quot;">​</a></h3><p>Note that these configuration variables should probably be set using the <strong>--global</strong> flag, for example like this:</p><blockquote><pre><code>$ git config --global web.browser firefox
</code></pre></blockquote><p>as they are probably more user specific than repository specific. See <strong>git-config</strong>(1) for more information about this.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,50);function c(e,b,h,u,d,g){return t(),a("div",null,[s("h1",l,r(e.$params.man),1),p])}const w=o(n,[["render",c]]);export{k as __pageData,w as default};
